use std::sync::mpsc::sync_channel;

let (tx, rx) = sync_channel::<Frame>(64);   // bounded; 0 = rendezvous
std::thread::spawn(move || {
    for f in source {
        if tx.send(f).is_err() { break; }   // blocks while the buffer is full
    }
});
for frame in rx {                           // consumer
    process(frame);
}

// The Sink contract: readiness before data.
// fn poll_ready(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<(), Error>>
//   Poll::Pending  => full: yield until woken (backpressure)
//   Poll::Ready(Ok(())) => start_send may be called now

sink.send(item).await?;          // futures::SinkExt: poll_ready + start_send
sink.send_all(&mut stream).await?;   // propagates backpressure end to end
sink.close().await?;                 // flush the tail

